        {
          "tag": "h1",
          "value": "Verify a corpus together with its provenance"
        },
        {
          "tag": "p",
          "value": "Link selected corpus bytes to source provenance, verify a complete manifest-backed bundle, and preserve acquisition limits across interruption using an offline Rust fixture.",
          "class": "lesson-description"
        },
        {
          "tag": "p",
          "value": "Admit a complete corpus bundle only when its source provenance, canonical manifest and all available payload bytes agree, while preserving acquisition limits across interruption."
        },
        {
          "tag": "p",
          "value": "Quick reference",
          "class": "cheat-sheet-eyebrow"
        },
        {
          "tag": "h2",
          "value": "A verified corpus bundle"
        },
        {
          "tag": "button",
          "attribute": "aria-label",
