// Restart-safe admission: an attempt and its first grant are persisted before
// transport, and an interrupted grant is charged once, never refunded.

use std::fs::File;
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::Path;

use headers::Header;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use super::canonical_manifest::{MAX_MANIFEST_BYTES, STREAM_BUFFER_BYTES, lower_sha256};
use super::inventory::Directory;
use super::lineage::{AcquisitionError, DatasetPolicy};

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BodyGrant {
    pub bytes: u64,
    pub sequence: u64,
    pub source_index: usize,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct SourceProgress {
    acknowledged_body_bytes: u64,
    attempts: u8,
    body_eof: bool,
    partial_bytes: u64,
    partial_sha256: String,
    redirects: u8,
    source_id: String,
    strong_validator: Option<String>,
    verified: bool,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AcquisitionProgressV1 {
    deadline_unix_seconds: u64,
    last_observed_unix_seconds: u64,
    next_grant_sequence: u64,
    outstanding_grant: Option<BodyGrant>,
    policy_sha256: String,
    schema_version: u32,
    source_index: usize,
    sources: Vec<SourceProgress>,
    started_at_unix_seconds: u64,
    uncertain_body_bytes: u64,
}

impl AcquisitionProgressV1 {
    pub fn new(policy: &DatasetPolicy, now: u64) -> Result<Self, AcquisitionError> {
        let empty = format!("{:x}", Sha256::digest([]));
        Ok(Self {
            deadline_unix_seconds: now
                .checked_add(policy.wall_seconds())
                .ok_or(AcquisitionError::Deadline)?,
            last_observed_unix_seconds: now,
            next_grant_sequence: 1,
            outstanding_grant: None,
            policy_sha256: policy.digest()?.as_hex().into(),
            schema_version: 1,
            source_index: 0,
            sources: policy
                .sources()
                .iter()
                .map(|source| SourceProgress {
                    acknowledged_body_bytes: 0,
                    attempts: 0,
                    body_eof: false,
                    partial_bytes: 0,
                    partial_sha256: empty.clone(),
                    redirects: 0,
                    source_id: source.source_id.clone(),
                    strong_validator: None,
                    verified: false,
                })
                .collect(),
            started_at_unix_seconds: now,
            uncertain_body_bytes: 0,
        })
    }

    pub fn acknowledged_body_bytes(&self) -> Result<u64, AcquisitionError> {
        self.sources.iter().try_fold(0_u64, |sum, source| {
            sum.checked_add(source.acknowledged_body_bytes)
                .ok_or(AcquisitionError::TransferBudget)
        })
    }
    pub fn uncertain_body_bytes(&self) -> u64 {
        self.uncertain_body_bytes
    }
    pub fn deadline_unix_seconds(&self) -> u64 {
        self.deadline_unix_seconds
    }
    pub fn charged_bytes(&self) -> Result<u64, AcquisitionError> {
        self.acknowledged_body_bytes()?
            .checked_add(self.uncertain_body_bytes)
            .and_then(|sum| {
                sum.checked_add(
                    self.outstanding_grant
                        .as_ref()
                        .map_or(0, |grant| grant.bytes),
                )
            })
            .ok_or(AcquisitionError::TransferBudget)
    }
    pub fn source_index(&self) -> usize {
        self.source_index
    }
    pub fn partial_bytes(&self) -> u64 {
        self.sources
            .get(self.source_index)
            .map_or(0, |s| s.partial_bytes)
    }
    pub fn attempts(&self, index: usize) -> Option<u8> {
        self.sources.get(index).map(|s| s.attempts)
    }
    pub fn redirects(&self, index: usize) -> Option<u8> {
        self.sources.get(index).map(|s| s.redirects)
    }
    pub fn outstanding_grant(&self) -> Option<&BodyGrant> {
        self.outstanding_grant.as_ref()
    }
    pub fn is_complete(&self) -> bool {
        self.source_index == 2 && self.outstanding_grant.is_none()
    }
    pub fn validator(&self) -> Option<&str> {
        self.sources
            .get(self.source_index)
            .and_then(|s| s.strong_validator.as_deref())
    }

    pub fn canonical_bytes(&self) -> Result<Vec<u8>, AcquisitionError> {
        let mut bytes = serde_json::to_vec(self).map_err(|_| AcquisitionError::Progress)?;
        bytes.push(b'\n');
        if bytes.len() > MAX_MANIFEST_BYTES {
            return Err(AcquisitionError::ManifestBound);
        }
        Ok(bytes)
    }

    fn validate(&self, policy: &DatasetPolicy, now: u64) -> Result<(), AcquisitionError> {
        if self.schema_version != 1
            || self.policy_sha256 != policy.digest()?.as_hex()
            || self.sources.len() != 2
            || self.source_index > 2
            || self.next_grant_sequence == 0
            || self.deadline_unix_seconds
                != self
                    .started_at_unix_seconds
                    .checked_add(policy.wall_seconds())
                    .ok_or(AcquisitionError::Deadline)?
        {
            return Err(AcquisitionError::Progress);
        }
        if now < self.last_observed_unix_seconds
            || now < self.started_at_unix_seconds
            || now > self.deadline_unix_seconds
        {
            return Err(AcquisitionError::Deadline);
        }
        for (i, (source, expected)) in self.sources.iter().zip(policy.sources()).enumerate() {
            if source.source_id != expected.source_id
                || source.attempts > 3
                || source.redirects > 5
                || source.partial_bytes > expected.bytes
                || !lower_sha256(&source.partial_sha256)
                || source.partial_bytes > source.acknowledged_body_bytes
                || source.verified != (i < self.source_index)
                || (source.verified
                    && (source.partial_bytes != expected.bytes
                        || source.partial_sha256 != expected.sha256))
                || (source.body_eof && source.partial_bytes != expected.bytes)
                || (i > self.source_index
                    && (source.attempts != 0 || source.partial_bytes != 0 || source.body_eof))
            {
                return Err(AcquisitionError::Progress);
            }
            if let Some(validator) = &source.strong_validator {
                strong_etag(validator)?;
            }
        }
        if let Some(grant) = &self.outstanding_grant
            && (grant.source_index != self.source_index
                || grant.source_index >= 2
                || grant.sequence == 0
                || grant.sequence >= self.next_grant_sequence
                || grant.bytes > STREAM_BUFFER_BYTES as u64)
        {
            return Err(AcquisitionError::Grant);
        }
        if self.charged_bytes()? > policy.body_ceiling() {
            return Err(AcquisitionError::TransferBudget);
        }
        Ok(())
    }

    fn grant(&mut self, policy: &DatasetPolicy) -> Result<BodyGrant, AcquisitionError> {
        if self.outstanding_grant.is_some() || self.source_index >= 2 {
            return Err(AcquisitionError::Grant);
        }
        if self.sources[self.source_index].body_eof {
            return Err(AcquisitionError::Incomplete);
        }
        let balance = policy
            .body_ceiling()
            .checked_sub(self.charged_bytes()?)
            .ok_or(AcquisitionError::TransferBudget)?;
        let grant = BodyGrant {
            bytes: balance.min(STREAM_BUFFER_BYTES as u64),
            sequence: self.next_grant_sequence,
            source_index: self.source_index,
        };
        self.next_grant_sequence = self
            .next_grant_sequence
            .checked_add(1)
            .ok_or(AcquisitionError::Grant)?;
        self.outstanding_grant = Some(grant.clone());
        Ok(grant)
    }

    /// Pure transaction: failed admission leaves all state and counters unchanged.
    pub fn begin_request(
        &mut self,
        policy: &DatasetPolicy,
        now: u64,
    ) -> Result<BodyGrant, AcquisitionError> {
        self.validate(policy, now)?;
        if self.outstanding_grant.is_some() || self.source_index >= 2 {
            return Err(AcquisitionError::Grant);
        }
        let remaining =
            self.sources
                .iter()
                .zip(policy.sources())
                .try_fold(0_u64, |sum, (s, p)| {
                    sum.checked_add(p.bytes - s.partial_bytes)
                        .ok_or(AcquisitionError::TransferBudget)
                })?;
        if self
            .charged_bytes()?
            .checked_add(remaining)
            .ok_or(AcquisitionError::TransferBudget)?
            > policy.body_ceiling()
        {
            return Err(AcquisitionError::TransferBudget);
        }
        if self.sources[self.source_index].attempts >= 3 {
            return Err(AcquisitionError::AttemptLimit);
        }
        if self.partial_bytes() != 0 && self.validator().is_none() {
            return Err(AcquisitionError::Validator);
        }
        let mut next = self.clone();
        next.sources[next.source_index].attempts += 1;
        next.last_observed_unix_seconds = now;
        let grant = next.grant(policy)?;
        *self = next;
        Ok(grant)
    }

    pub fn follow_redirect(
        &mut self,
        policy: &DatasetPolicy,
        now: u64,
    ) -> Result<BodyGrant, AcquisitionError> {
        self.validate(policy, now)?;
        if self.source_index >= 2
            || self.outstanding_grant.is_some()
            || self.sources[self.source_index].attempts == 0
        {
            return Err(AcquisitionError::Grant);
        }
        if self.sources[self.source_index].redirects >= 5 {
            return Err(AcquisitionError::RedirectLimit);
        }
        let mut next = self.clone();
        next.sources[next.source_index].redirects += 1;
        next.last_observed_unix_seconds = now;
        let grant = next.grant(policy)?;
        *self = next;
        Ok(grant)
    }

    pub fn next_grant(
        &mut self,
        policy: &DatasetPolicy,
        now: u64,
    ) -> Result<BodyGrant, AcquisitionError> {
        self.validate(policy, now)?;
        let mut next = self.clone();
        next.last_observed_unix_seconds = now;
        let grant = next.grant(policy)?;
        *self = next;
        Ok(grant)
    }

    fn settle(
        &mut self,
        policy: &DatasetPolicy,
        now: u64,
        sequence: u64,
        delivered: u64,
        retained: Option<(u64, String)>,
    ) -> Result<(), AcquisitionError> {
        self.validate(policy, now)?;
        let grant = self
            .outstanding_grant
            .as_ref()
            .ok_or(AcquisitionError::Grant)?;
        if grant.sequence != sequence || delivered > grant.bytes {
            return Err(AcquisitionError::Grant);
        }
        let mut next = self.clone();
        let source = &mut next.sources[next.source_index];
        source.acknowledged_body_bytes = source
            .acknowledged_body_bytes
            .checked_add(delivered)
            .ok_or(AcquisitionError::TransferBudget)?;
        if let Some((bytes, digest)) = retained {
            if bytes
                != source
                    .partial_bytes
                    .checked_add(delivered)
                    .ok_or(AcquisitionError::Size)?
                || bytes > policy.sources()[next.source_index].bytes
                || !lower_sha256(&digest)
            {
                return Err(AcquisitionError::Size);
            }
            source.partial_bytes = bytes;
            source.partial_sha256 = digest;
        }
        next.outstanding_grant = None;
        next.last_observed_unix_seconds = now;
        *self = next;
        Ok(())
    }

    /// A crash loses certainty, not budget. The active slot is cleared in the
    /// same update, so recovery repeated on that update cannot charge it twice.
    pub fn recover(&mut self, policy: &DatasetPolicy, now: u64) -> Result<(), AcquisitionError> {
        self.validate(policy, now)?;
        let mut next = self.clone();
        if let Some(grant) = next.outstanding_grant.take() {
            next.uncertain_body_bytes = next
                .uncertain_body_bytes
                .checked_add(grant.bytes)
                .ok_or(AcquisitionError::TransferBudget)?;
        }
        next.last_observed_unix_seconds = now;
        *self = next;
        Ok(())
    }
}

fn strong_etag(input: &str) -> Result<headers::ETag, AcquisitionError> {
    if input.len() > 1024 {
        return Err(AcquisitionError::Validator);
    }
    let tag: headers::ETag = input.parse().map_err(|_| AcquisitionError::Validator)?;
    if tag.is_weak() {
        return Err(AcquisitionError::Validator);
    }
    Ok(tag)
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ResponseHead {
    pub content_encoding: Vec<String>,
    pub content_length: Vec<String>,
    pub content_range: Vec<String>,
    pub content_type: Vec<String>,
    pub etag: Vec<String>,
    pub status: u16,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AcceptedResponse {
    validator: Option<String>,
}

pub fn admit_response(
    head: &ResponseHead,
    offset: u64,
    expected_bytes: u64,
    previous_validator: Option<&str>,
) -> Result<AcceptedResponse, AcquisitionError> {
    for values in [
        &head.content_encoding,
        &head.content_length,
        &head.content_range,
        &head.content_type,
        &head.etag,
    ] {
        if values.len() > 1 || values.iter().any(|value| value.len() > 8192) {
            return Err(AcquisitionError::Schema);
        }
    }
    if head
        .content_encoding
        .first()
        .is_some_and(|value| !value.eq_ignore_ascii_case("identity"))
    {
        return Err(AcquisitionError::Encoding);
    }
    let content_type: headers::ContentType = head
        .content_type
        .first()
        .ok_or(AcquisitionError::Media)?
        .parse()
        .map_err(|_| AcquisitionError::Media)?;
    if content_type != headers::ContentType::text()
        && content_type != headers::ContentType::text_utf8()
    {
        return Err(AcquisitionError::Media);
    }
    let validator = head
        .etag
        .first()
        .map(|value| strong_etag(value).map(|_| value.clone()))
        .transpose()?;
    if offset == 0 {
        if head.status != 200 || !head.content_range.is_empty() {
            return Err(AcquisitionError::Range);
        }
    } else {
        if head.status != 206 || offset >= expected_bytes {
            return Err(AcquisitionError::Range);
        }
        let value = head.content_range.first().ok_or(AcquisitionError::Range)?;
        let header_value = value
            .parse::<headers::HeaderValue>()
            .map_err(|_| AcquisitionError::Range)?;
        let range = headers::ContentRange::decode(&mut std::iter::once(&header_value))
            .map_err(|_| AcquisitionError::Range)?;
        if range.bytes_range() != Some((offset, expected_bytes - 1))
            || range.bytes_len() != Some(expected_bytes)
        {
            return Err(AcquisitionError::Range);
        }
        let previous = strong_etag(previous_validator.ok_or(AcquisitionError::Validator)?)?;
        let observed = strong_etag(validator.as_deref().ok_or(AcquisitionError::Validator)?)?;
        if !headers::IfMatch::from(previous).precondition_passes(&observed) {
            return Err(AcquisitionError::Validator);
        }
    }
    if let Some(value) = head.content_length.first() {
        let header_value = value
            .parse::<headers::HeaderValue>()
            .map_err(|_| AcquisitionError::Size)?;
        let length = headers::ContentLength::decode(&mut std::iter::once(&header_value))
            .map_err(|_| AcquisitionError::Size)?;
        if length.0
            != expected_bytes
                .checked_sub(offset)
                .ok_or(AcquisitionError::Range)?
        {
            return Err(AcquisitionError::Size);
        }
    }
    Ok(AcceptedResponse { validator })
}

/// One owner holds a stable lock inode while replacing progress.json. Returned
/// grants exist only after the corresponding replacement and parent sync pass.
pub struct ProgressStore {
    directory: Directory,
    _lock: File,
    policy: DatasetPolicy,
    progress: AcquisitionProgressV1,
    accepted_response: bool,
    prefix_hasher: Sha256,
    process_started: std::time::Instant,
    process_wall_start: u64,
}

impl ProgressStore {
    pub fn create(path: &Path, policy: DatasetPolicy, now: u64) -> Result<Self, AcquisitionError> {
        let directory = Directory::open(path)?;
        let lock = directory.lock()?;
        // Never initialize over an old record, including malformed state.
        if directory.file("progress.json", false, false).is_ok() {
            return Err(AcquisitionError::Progress);
        }
        let progress = AcquisitionProgressV1::new(&policy, now)?;
        // Exclusive initial marker prevents an unreadable old progress record
        // from being mistaken for absence before the first atomic replacement.
        let mut initial = directory.file("progress.json", true, true)?;
        initial
            .write_all(&progress.canonical_bytes()?)
            .map_err(|_| AcquisitionError::Io)?;
        initial.sync_all().map_err(|_| AcquisitionError::Io)?;
        directory.sync()?;
        Ok(Self {
            directory,
            _lock: lock,
            policy,
            progress,
            accepted_response: false,
            prefix_hasher: Sha256::new(),
            process_started: std::time::Instant::now(),
            process_wall_start: now,
        })
    }

    pub fn restore(path: &Path, policy: DatasetPolicy, now: u64) -> Result<Self, AcquisitionError> {
        let directory = Directory::open(path)?;
        let lock = directory.lock()?;
        let mut input = directory.file("progress.json", false, false)?;
        let mut bytes = Vec::new();
        Read::by_ref(&mut input)
            .take(MAX_MANIFEST_BYTES as u64 + 1)
            .read_to_end(&mut bytes)
            .map_err(|_| AcquisitionError::Io)?;
        if bytes.len() > MAX_MANIFEST_BYTES {
            return Err(AcquisitionError::ManifestBound);
        }
        let mut progress: AcquisitionProgressV1 =
            serde_json::from_slice(&bytes).map_err(|_| AcquisitionError::Progress)?;
        if progress.canonical_bytes()? != bytes {
            return Err(AcquisitionError::NonCanonical);
        }
        progress.validate(&policy, now)?;
        let mut owner = Self {
            directory,
            _lock: lock,
            policy,
            progress: progress.clone(),
            accepted_response: false,
            prefix_hasher: Sha256::new(),
            process_started: std::time::Instant::now(),
            process_wall_start: now,
        };
        progress.recover(&owner.policy, now)?;
        owner.commit(progress)?;
        owner.verify_recorded_partials()?;
        Ok(owner)
    }

    pub fn progress(&self) -> &AcquisitionProgressV1 {
        &self.progress
    }

    fn check_clock(&self, now: u64) -> Result<(), AcquisitionError> {
        self.progress.validate(&self.policy, now)?;
        let remaining = self
            .progress
            .deadline_unix_seconds
            .checked_sub(self.process_wall_start)
            .ok_or(AcquisitionError::Deadline)?;
        if self.process_started.elapsed() > std::time::Duration::from_secs(remaining) {
            return Err(AcquisitionError::Deadline);
        }
        Ok(())
    }

    fn commit(&mut self, next: AcquisitionProgressV1) -> Result<(), AcquisitionError> {
        self.directory.atomic_record(&next.canonical_bytes()?)?;
        self.progress = next;
        Ok(())
    }

    pub fn begin_request(&mut self, now: u64) -> Result<BodyGrant, AcquisitionError> {
        self.check_clock(now)?;
        let mut next = self.progress.clone();
        let grant = next.begin_request(&self.policy, now)?;
        self.commit(next)?;
        self.accepted_response = false;
        Ok(grant)
    }

    pub fn next_grant(&mut self, now: u64) -> Result<BodyGrant, AcquisitionError> {
        self.check_clock(now)?;
        if self.progress.source_index >= 2
            || self.progress.sources[self.progress.source_index].body_eof
        {
            return Err(AcquisitionError::Incomplete);
        }
        let mut next = self.progress.clone();
        let grant = next.next_grant(&self.policy, now)?;
        self.commit(next)?;
        Ok(grant)
    }

    pub fn follow_redirect(&mut self, url: &str, now: u64) -> Result<BodyGrant, AcquisitionError> {
        self.check_clock(now)?;
        let _ = self.policy.admit_endpoint(url)?;
        let mut next = self.progress.clone();
        let grant = next.follow_redirect(&self.policy, now)?;
        self.commit(next)?;
        self.accepted_response = false;
        Ok(grant)
    }

    pub fn accept_head(&mut self, head: &ResponseHead, now: u64) -> Result<(), AcquisitionError> {
        self.check_clock(now)?;
        if self.progress.outstanding_grant.is_none() {
            return Err(AcquisitionError::Grant);
        }
        let index = self.progress.source_index;
        let accepted = admit_response(
            head,
            self.progress.partial_bytes(),
            self.policy.sources()[index].bytes,
            self.progress.validator(),
        )?;
        let mut next = self.progress.clone();
        next.sources[index].strong_validator = accepted.validator;
        next.last_observed_unix_seconds = now;
        self.commit(next)?;
        self.accepted_response = true;
        Ok(())
    }

    /// Only this method derives prefix evidence from bytes it actually writes.
    /// Error/redirect bytes are acknowledged with retain=false and never enter
    /// the corpus partial. Unknown delivery remains an unsettled grant.
    pub fn receive(
        &mut self,
        sequence: u64,
        bytes: &[u8],
        retain: bool,
        now: u64,
    ) -> Result<(), AcquisitionError> {
        self.check_clock(now)?;
        if bytes.is_empty() {
            return Err(AcquisitionError::Grant);
        }
        let grant = self
            .progress
            .outstanding_grant
            .as_ref()
            .ok_or(AcquisitionError::Grant)?;
        if grant.sequence != sequence
            || bytes.len() as u64 > grant.bytes
            || (retain && !self.accepted_response)
        {
            return Err(AcquisitionError::Grant);
        }
        let mut next_hasher = self.prefix_hasher.clone();
        let retained = if retain {
            let index = self.progress.source_index;
            let new_length = self
                .progress
                .partial_bytes()
                .checked_add(bytes.len() as u64)
                .ok_or(AcquisitionError::Size)?;
            if new_length > self.policy.sources()[index].bytes {
                return Err(AcquisitionError::Size);
            }
            let name = format!("source-{index}.partial");
            let mut file = if self.progress.partial_bytes() == 0 {
                self.directory.file(&name, true, true)?
            } else {
                self.directory.file(&name, true, false)?
            };
            file.seek(SeekFrom::End(0))
                .map_err(|_| AcquisitionError::Io)?;
            if file.stream_position().map_err(|_| AcquisitionError::Io)?
                != self.progress.partial_bytes()
            {
                return Err(AcquisitionError::Progress);
            }
            file.write_all(bytes).map_err(|_| AcquisitionError::Io)?;
            file.sync_all().map_err(|_| AcquisitionError::Io)?;
            self.directory.sync()?;
            // Hash incrementally; rehash the recorded prefix once on restore
            // and the complete file once at finalization, not once per chunk.
            next_hasher.update(bytes);
            let digest = format!("{:x}", next_hasher.clone().finalize());
            Some((new_length, digest))
        } else {
            None
        };
        let mut next = self.progress.clone();
        next.settle(&self.policy, now, sequence, bytes.len() as u64, retained)?;
        self.commit(next)?;
        if retain {
            self.prefix_hasher = next_hasher;
        }
        Ok(())
    }

    /// EOF is a separate transport notification. A zero-byte grant can settle
    /// this notification even when no nonempty delivery remains admissible.
    pub fn acknowledge_eof(&mut self, sequence: u64, now: u64) -> Result<(), AcquisitionError> {
        self.check_clock(now)?;
        if !self.accepted_response {
            return Err(AcquisitionError::Incomplete);
        }
        let index = self.progress.source_index;
        if index >= 2 || self.progress.partial_bytes() != self.policy.sources()[index].bytes {
            return Err(AcquisitionError::Size);
        }
        if self.policy.sources()[index].bytes == 0 {
            let file = self
                .directory
                .file(&format!("source-{index}.partial"), true, true)?;
            file.sync_all().map_err(|_| AcquisitionError::Io)?;
            self.directory.sync()?;
        }
        let mut next = self.progress.clone();
        next.settle(&self.policy, now, sequence, 0, None)?;
        next.sources[index].body_eof = true;
        self.commit(next)
    }

    /// A transport that cancelled before delivering any bytes to the policy
    /// interface may release this grant. This says nothing about socket ingress.
    pub fn cancel_body(&mut self, sequence: u64, now: u64) -> Result<(), AcquisitionError> {
        self.check_clock(now)?;
        let mut next = self.progress.clone();
        next.settle(&self.policy, now, sequence, 0, None)?;
        self.commit(next)?;
        self.accepted_response = false;
        Ok(())
    }

    pub fn finish_file(&mut self, now: u64) -> Result<(), AcquisitionError> {
        self.check_clock(now)?;
        if self.progress.outstanding_grant.is_some() || self.progress.source_index >= 2 {
            return Err(AcquisitionError::Incomplete);
        }
        let index = self.progress.source_index;
        let source = &self.progress.sources[index];
        let expected = &self.policy.sources()[index];
        if !source.body_eof {
            return Err(AcquisitionError::Incomplete);
        }
        if source.partial_bytes != expected.bytes {
            return Err(AcquisitionError::Size);
        }
        let mut file = self
            .directory
            .file(&format!("source-{index}.partial"), false, false)?;
        if digest_file(&mut file, expected.bytes)? != expected.sha256 {
            return Err(AcquisitionError::Hash);
        }
        let mut next = self.progress.clone();
        next.sources[index].verified = true;
        next.source_index += 1;
        next.last_observed_unix_seconds = now;
        self.commit(next)?;
        self.accepted_response = false;
        self.prefix_hasher = Sha256::new();
        Ok(())
    }

    fn verify_recorded_partials(&mut self) -> Result<(), AcquisitionError> {
        for (index, source) in self.progress.sources.iter().enumerate() {
            let name = format!("source-{index}.partial");
            let file = self.directory.file(&name, false, false);
            if source.partial_bytes == 0 {
                // An unreceipted write cannot establish a verified prefix.
                if file.is_ok() && !source.body_eof {
                    self.directory.quarantine_partial(index)?;
                    return Err(AcquisitionError::Progress);
                }
                if let Err(error) = &file
                    && *error != AcquisitionError::Io
                {
                    return Err(*error);
                }
                if !source.body_eof {
                    continue;
                }
            }
            let mut file = file?;
            let hasher = match file_hasher(&mut file, source.partial_bytes) {
                Ok(hasher) => hasher,
                Err(error @ (AcquisitionError::Size | AcquisitionError::Hash)) => {
                    self.directory.quarantine_partial(index)?;
                    return Err(error);
                }
                Err(error) => return Err(error),
            };
            if format!("{:x}", hasher.clone().finalize()) != source.partial_sha256 {
                self.directory.quarantine_partial(index)?;
                return Err(AcquisitionError::Hash);
            }
            if index == self.progress.source_index {
                self.prefix_hasher = hasher;
            }
        }
        Ok(())
    }
}

fn digest_file(file: &mut File, expected: u64) -> Result<String, AcquisitionError> {
    Ok(format!("{:x}", file_hasher(file, expected)?.finalize()))
}

fn file_hasher(file: &mut File, expected: u64) -> Result<Sha256, AcquisitionError> {
    if file.metadata().map_err(|_| AcquisitionError::Io)?.len() != expected {
        return Err(AcquisitionError::Size);
    }
    file.seek(SeekFrom::Start(0))
        .map_err(|_| AcquisitionError::Io)?;
    let mut hasher = Sha256::new();
    let mut buffer = [0_u8; STREAM_BUFFER_BYTES];
    let mut total = 0_u64;
    loop {
        let count = file.read(&mut buffer).map_err(|_| AcquisitionError::Io)?;
        if count == 0 {
            break;
        }
        total = total
            .checked_add(count as u64)
            .ok_or(AcquisitionError::Size)?;
        if total > expected {
            return Err(AcquisitionError::Size);
        }
        hasher.update(&buffer[..count]);
    }
    if total != expected {
        return Err(AcquisitionError::Size);
    }
    Ok(hasher)
}

// Exact, closed dataset-manifest bytes. JSON syntax belongs to Serde;
// schema, ordering and byte identity belong to the course.

use serde::{Deserialize, Serialize};

use super::lineage::AcquisitionError;
use crate::artifact_identity::{ArtifactDigest, sha256};

pub const MAX_MANIFEST_BYTES: usize = 1_048_576;
pub const MAX_METADATA_BYTES: u64 = 1_048_576;
pub const STREAM_BUFFER_BYTES: usize = 65_536;

// Declaration order is UTF-8 key order at every object level. Arrays have
// separately checked semantic order; serialization does not sort those arrays.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DatasetArtifactManifestV1 {
    pub dataset_scope: DatasetScope,
    pub kind: String,
    pub payload: Vec<PayloadEntry>,
    pub producer: Producer,
    pub redistribution: Redistribution,
    pub schema_version: u32,
    pub sources: Vec<SourceRecord>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DatasetScope {
    pub domain: String,
    pub language: String,
    pub selected_source: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PayloadEntry {
    pub bytes: u64,
    pub media_type: String,
    pub path: String,
    pub role: String,
    pub sha256: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Producer {
    pub config_sha256: String,
    pub script_sha256: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Redistribution {
    pub adapter: String,
    pub derived_model: String,
    pub raw_input: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SourceRecord {
    pub attribution_path: String,
    pub attribution_references: Vec<String>,
    pub attribution_sha256: String,
    pub bytes: u64,
    pub filter_config_sha256: Option<String>,
    pub filter_script_sha256: Option<String>,
    pub license_id: String,
    pub license_path: String,
    pub license_text_sha256: String,
    pub media_type: String,
    pub payload_path: String,
    pub requested_url: String,
    pub resolved_url: RedactedEndpoint,
    pub sha256: String,
    pub source_id: String,
    pub source_kind: String,
    pub upstream_revision: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RedactedEndpoint {
    pub host: String,
    pub path: String,
    pub query_key_inventory_sha256: String,
    pub query_keys: Vec<String>,
    pub query_values_redacted: bool,
    pub scheme: String,
    pub transport_caps_passed: bool,
}

pub fn lower_sha256(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

/// The codec retains repeated query-key occurrences. Only values are omitted.
pub fn query_inventory_digest(keys: &[String]) -> Result<ArtifactDigest, AcquisitionError> {
    let mut sorted = keys.to_vec();
    sorted.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));
    let mut bytes = serde_json::to_vec(&sorted).map_err(|_| AcquisitionError::Schema)?;
    bytes.push(b'\n');
    if bytes.len() > MAX_MANIFEST_BYTES {
        return Err(AcquisitionError::ManifestBound);
    }
    Ok(sha256(&bytes))
}

pub fn portable_payload_path(path: &str) -> bool {
    !path.is_empty()
        && path.len() <= 256
        && path.split('/').all(|part| {
            !part.is_empty()
                && part != "."
                && part != ".."
                && part
                    .bytes()
                    .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.'))
        })
}

pub fn validate_manifest_structure(
    manifest: &DatasetArtifactManifestV1,
) -> Result<(), AcquisitionError> {
    if manifest.schema_version != 1 || manifest.kind != "dataset" {
        return Err(AcquisitionError::Schema);
    }
    if manifest.payload.len() != 4 || manifest.sources.len() != 2 {
        return Err(AcquisitionError::Inventory);
    }
    if !lower_sha256(&manifest.producer.config_sha256)
        || !lower_sha256(&manifest.producer.script_sha256)
    {
        return Err(AcquisitionError::Policy);
    }
    let redistribution = &manifest.redistribution;
    if [
        &redistribution.adapter,
        &redistribution.derived_model,
        &redistribution.raw_input,
    ]
    .iter()
    .any(|v| v.as_str() != "not-approved")
    {
        return Err(AcquisitionError::Metadata);
    }
    let mut folded_paths = std::collections::BTreeSet::new();
    let mut total = 0_u64;
    for (i, entry) in manifest.payload.iter().enumerate() {
        if !portable_payload_path(&entry.path)
            || !folded_paths.insert(entry.path.to_ascii_lowercase())
        {
            return Err(AcquisitionError::UnsafePath);
        }
        if i > 0 && manifest.payload[i - 1].path.as_bytes() >= entry.path.as_bytes() {
            return Err(AcquisitionError::Inventory);
        }
        if !lower_sha256(&entry.sha256) || entry.media_type != "text/plain" {
            return Err(AcquisitionError::Metadata);
        }
        if matches!(entry.role.as_str(), "license" | "attribution")
            && (entry.bytes == 0 || entry.bytes > MAX_METADATA_BYTES)
        {
            return Err(AcquisitionError::Metadata);
        }
        total = total
            .checked_add(entry.bytes)
            .ok_or(AcquisitionError::Size)?;
    }
    let _ = total;
    for (i, source) in manifest.sources.iter().enumerate() {
        if source.source_kind
            != if i == 0 {
                "raw-corpus"
            } else {
                "raw-heldout-source"
            }
            || source.filter_config_sha256.is_some()
            || source.filter_script_sha256.is_some()
            || source.media_type != "text/plain"
            || source.attribution_references.is_empty()
            || source.attribution_references.len() > 16
        {
            return Err(AcquisitionError::Metadata);
        }
        for (path, digest, role) in [
            (
                &source.payload_path,
                &source.sha256,
                if i == 0 {
                    "raw-train"
                } else {
                    "raw-validation"
                },
            ),
            (&source.license_path, &source.license_text_sha256, "license"),
            (
                &source.attribution_path,
                &source.attribution_sha256,
                "attribution",
            ),
        ] {
            let entry = manifest
                .payload
                .iter()
                .find(|entry| &entry.path == path)
                .ok_or(AcquisitionError::Inventory)?;
            if &entry.sha256 != digest
                || entry.role != role
                || (path == &source.payload_path && entry.bytes != source.bytes)
            {
                return Err(AcquisitionError::Metadata);
            }
        }
        let endpoint = &source.resolved_url;
        if endpoint.scheme != "https"
            || !endpoint.query_values_redacted
            || !endpoint.transport_caps_passed
            || endpoint.query_keys.len() > 128
            || endpoint.query_keys.iter().any(|key| key.len() > 1024)
            || endpoint
                .query_keys
                .windows(2)
                .any(|w| w[0].as_bytes() > w[1].as_bytes())
            || query_inventory_digest(&endpoint.query_keys)?.as_hex()
                != endpoint.query_key_inventory_sha256
        {
            return Err(AcquisitionError::Metadata);
        }
    }
    if manifest.sources[0].license_path != manifest.sources[1].license_path
        || manifest.sources[0].attribution_path != manifest.sources[1].attribution_path
    {
        return Err(AcquisitionError::Metadata);
    }
    Ok(())
}

pub fn canonical_manifest_bytes(
    manifest: &DatasetArtifactManifestV1,
) -> Result<Vec<u8>, AcquisitionError> {
    validate_manifest_structure(manifest)?;
    let mut bytes = serde_json::to_vec(manifest).map_err(|_| AcquisitionError::Schema)?;
    bytes.push(b'\n');
    if bytes.len() > MAX_MANIFEST_BYTES {
        return Err(AcquisitionError::ManifestBound);
    }
    Ok(bytes)
}

/// Parse typed closed objects first: Serde rejects duplicate struct fields.
/// Then compare the complete original bytes, including its one final LF.
pub fn parse_dataset_manifest(bytes: &[u8]) -> Result<DatasetArtifactManifestV1, AcquisitionError> {
    if bytes.len() > MAX_MANIFEST_BYTES {
        return Err(AcquisitionError::ManifestBound);
    }
    let manifest = serde_json::from_slice(bytes).map_err(|_| AcquisitionError::Schema)?;
    if canonical_manifest_bytes(&manifest)? != bytes {
        return Err(AcquisitionError::NonCanonical);
    }
    Ok(manifest)
}

// region:dataset-artifact-identity
pub fn artifact_id(
    manifest: &DatasetArtifactManifestV1,
) -> Result<ArtifactDigest, AcquisitionError> {
    Ok(sha256(&canonical_manifest_bytes(manifest)?))
}
// endregion:dataset-artifact-identity

// Bounded streaming verification and descriptor-relative filesystem plumbing.
// Rustix supplies safe OS operations; course checks decide which objects count.

use std::collections::BTreeSet;
use std::fs::File;
use std::io::{Read, Write};
use std::os::fd::OwnedFd;
use std::path::{Component, Path};

use rustix::fs::{self, Dir, FileType, Mode, OFlags};
use sha2::{Digest, Sha256};

use super::canonical_manifest::{
    DatasetArtifactManifestV1, PayloadEntry, STREAM_BUFFER_BYTES, artifact_id,
    canonical_manifest_bytes, portable_payload_path,
};
use super::lineage::{AcquisitionError, DatasetPolicy};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VerifiedPayload {
    path: String,
    bytes: u64,
    sha256: String,
}
impl VerifiedPayload {
    pub fn path(&self) -> &str {
        &self.path
    }
    pub fn bytes(&self) -> u64 {
        self.bytes
    }
    pub fn sha256(&self) -> &str {
        &self.sha256
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VerifiedBundle {
    artifact_id: String,
    evidence_kind: String,
    files: Vec<VerifiedPayload>,
    total_bytes: u64,
}

/// Read one bounded manifest from an anchored parent without following links.
/// Structural parsing does not replace the caller's selected-source policy.
pub fn read_manifest(path: &Path) -> Result<DatasetArtifactManifestV1, AcquisitionError> {
    let parent = path.parent().ok_or(AcquisitionError::UnsafePath)?;
    let name = path
        .file_name()
        .and_then(|value| value.to_str())
        .ok_or(AcquisitionError::UnsafePath)?;
    let directory = Directory::open(parent)?;
    let mut file = directory.file(name, false, false)?;
    let mut bytes = Vec::new();
    Read::by_ref(&mut file)
        .take(1_048_577)
        .read_to_end(&mut bytes)
        .map_err(|_| AcquisitionError::Io)?;
    super::canonical_manifest::parse_dataset_manifest(&bytes)
}
impl VerifiedBundle {
    pub fn artifact_id(&self) -> &str {
        &self.artifact_id
    }
    pub fn evidence_kind(&self) -> &str {
        &self.evidence_kind
    }
    pub fn files(&self) -> &[VerifiedPayload] {
        &self.files
    }
    pub fn total_bytes(&self) -> u64 {
        self.total_bytes
    }
}

// region:bounded-payload-verification
pub fn verify_payload(
    expected: &PayloadEntry,
    reader: &mut impl Read,
) -> Result<VerifiedPayload, AcquisitionError> {
    let mut hasher = Sha256::new();
    let mut buffer = [0_u8; STREAM_BUFFER_BYTES];
    let mut total = 0_u64;
    loop {
        // Once expected bytes have arrived, one additional byte distinguishes
        // a real EOF from a same-prefix oversize object. Never retain that byte.
        let remaining = expected
            .bytes
            .checked_sub(total)
            .ok_or(AcquisitionError::Size)?;
        let allowance = remaining.min(STREAM_BUFFER_BYTES as u64) as usize;
        let count = loop {
            match reader.read(&mut buffer[..allowance.max(1)]) {
                Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,
                result => break result.map_err(|_| AcquisitionError::Io)?,
            }
        };
        if count == 0 {
            break;
        }
        total = total
            .checked_add(count as u64)
            .ok_or(AcquisitionError::Size)?;
        if total > expected.bytes {
            return Err(AcquisitionError::Size);
        }
        hasher.update(&buffer[..count]);
    }
    if total != expected.bytes {
        return Err(AcquisitionError::Size);
    }
    let digest = format!("{:x}", hasher.finalize());
    if digest != expected.sha256 {
        return Err(AcquisitionError::Hash);
    }
    Ok(VerifiedPayload {
        path: expected.path.clone(),
        bytes: total,
        sha256: digest,
    })
}
// endregion:bounded-payload-verification

/// An anchored directory descriptor, not an unrestricted path sandbox.
/// The caller owns the directory's authority and the single-writer lifecycle.
/// Every traversed component is opened without following links.
pub(crate) struct Directory {
    fd: OwnedFd,
}

impl Directory {
    pub(crate) fn open(path: &Path) -> Result<Self, AcquisitionError> {
        let start = if path.is_absolute() { "/" } else { "." };
        let mut fd = fs::open(
            start,
            OFlags::RDONLY | OFlags::DIRECTORY | OFlags::CLOEXEC,
            Mode::empty(),
        )
        .map_err(|_| AcquisitionError::Io)?;
        for part in path.components() {
            match part {
                Component::RootDir => (),
                Component::Normal(name) => {
                    fd = fs::openat(
                        &fd,
                        name,
                        OFlags::RDONLY | OFlags::DIRECTORY | OFlags::NOFOLLOW | OFlags::CLOEXEC,
                        Mode::empty(),
                    )
                    .map_err(|_| AcquisitionError::UnsafePath)?;
                }
                _ => return Err(AcquisitionError::UnsafePath),
            }
        }
        Ok(Self { fd })
    }

    pub(crate) fn child(&self, name: &str) -> Result<Self, AcquisitionError> {
        if !portable_payload_path(name) || name.contains('/') {
            return Err(AcquisitionError::UnsafePath);
        }
        let fd = fs::openat(
            &self.fd,
            name,
            OFlags::RDONLY | OFlags::DIRECTORY | OFlags::NOFOLLOW | OFlags::CLOEXEC,
            Mode::empty(),
        )
        .map_err(|_| AcquisitionError::UnsafePath)?;
        Ok(Self { fd })
    }

    pub(crate) fn create_child(&self, name: &str) -> Result<Self, AcquisitionError> {
        if !portable_payload_path(name) || name.contains('/') {
            return Err(AcquisitionError::UnsafePath);
        }
        fs::mkdirat(&self.fd, name, Mode::RWXU).map_err(|_| AcquisitionError::Io)?;
        self.sync()?;
        self.child(name)
    }

    pub(crate) fn file(
        &self,
        name: &str,
        writable: bool,
        create: bool,
    ) -> Result<File, AcquisitionError> {
        if !portable_payload_path(name) || name.contains('/') {
            return Err(AcquisitionError::UnsafePath);
        }
        if !create {
            let before = fs::statat(&self.fd, name, fs::AtFlags::SYMLINK_NOFOLLOW)
                .map_err(|_| AcquisitionError::Io)?;
            if FileType::from_raw_mode(before.st_mode) != FileType::RegularFile
                || before.st_nlink != 1
            {
                return Err(AcquisitionError::FileKind);
            }
        }
        let mut flags = if writable {
            OFlags::RDWR
        } else {
            OFlags::RDONLY
        };
        flags |= OFlags::NOFOLLOW | OFlags::CLOEXEC | OFlags::NONBLOCK;
        if create {
            flags |= OFlags::CREATE | OFlags::EXCL;
        }
        let fd = fs::openat(&self.fd, name, flags, Mode::RUSR | Mode::WUSR)
            .map_err(|_| AcquisitionError::Io)?;
        let stat = fs::fstat(&fd).map_err(|_| AcquisitionError::Io)?;
        if FileType::from_raw_mode(stat.st_mode) != FileType::RegularFile || stat.st_nlink != 1 {
            return Err(AcquisitionError::FileKind);
        }
        Ok(File::from(fd))
    }

    pub(crate) fn sync(&self) -> Result<(), AcquisitionError> {
        fs::fsync(&self.fd).map_err(|_| AcquisitionError::Io)
    }

    pub(crate) fn rename(&self, old: &str, new: &str) -> Result<(), AcquisitionError> {
        for name in [old, new] {
            if !portable_payload_path(name) || name.contains('/') {
                return Err(AcquisitionError::UnsafePath);
            }
        }
        fs::renameat(&self.fd, old, &self.fd, new).map_err(|_| AcquisitionError::Io)?;
        self.sync()
    }

    pub(crate) fn atomic_record(&self, bytes: &[u8]) -> Result<(), AcquisitionError> {
        // A leftover .next file means the previous write was interrupted. It
        // is preserved and refused, never blindly truncated or treated as good.
        let mut file = self.file("progress.next", true, true)?;
        file.write_all(bytes).map_err(|_| AcquisitionError::Io)?;
        file.sync_all().map_err(|_| AcquisitionError::Io)?;
        drop(file);
        self.rename("progress.next", "progress.json")
    }

    /// Preserve only this owner's known regular partial, without replacing an
    /// earlier diagnostic. Links and special files are refused, not followed.
    pub(crate) fn quarantine_partial(&self, index: usize) -> Result<(), AcquisitionError> {
        if index >= 2 {
            return Err(AcquisitionError::Progress);
        }
        let old = format!("source-{index}.partial");
        let new = format!("quarantine-source-{index}.partial");
        let _checked = self.file(&old, false, false)?;
        fs::renameat_with(&self.fd, &old, &self.fd, &new, fs::RenameFlags::NOREPLACE)
            .map_err(|_| AcquisitionError::Io)?;
        self.sync()
    }

    pub(crate) fn lock(&self) -> Result<File, AcquisitionError> {
        let file = match self.file("acquisition.lock", true, false) {
            Ok(file) => file,
            Err(AcquisitionError::Io) => self.file("acquisition.lock", true, true)?,
            Err(error) => return Err(error),
        };
        fs::flock(&file, fs::FlockOperation::NonBlockingLockExclusive)
            .map_err(|_| AcquisitionError::ConcurrentWriter)?;
        self.sync()?;
        Ok(file)
    }

    fn check_inventory(&self, expected: &[PayloadEntry]) -> Result<(), AcquisitionError> {
        fn walk(
            directory: &Directory,
            prefix: &str,
            expected: &[PayloadEntry],
            seen: &mut BTreeSet<String>,
            depth: usize,
        ) -> Result<(), AcquisitionError> {
            if depth > 4 {
                return Err(AcquisitionError::Inventory);
            }
            let mut stream = Dir::read_from(&directory.fd).map_err(|_| AcquisitionError::Io)?;
            while let Some(entry) = stream.read() {
                let entry = entry.map_err(|_| AcquisitionError::Io)?;
                let name = entry
                    .file_name()
                    .to_str()
                    .map_err(|_| AcquisitionError::UnsafePath)?;
                if matches!(name, "." | "..") {
                    continue;
                }
                let path = if prefix.is_empty() {
                    name.to_owned()
                } else {
                    format!("{prefix}/{name}")
                };
                if !portable_payload_path(&path) {
                    return Err(AcquisitionError::UnsafePath);
                }
                if expected.iter().any(|row| row.path == path) {
                    // Type/link checks are applied again on the opened descriptor.
                    let _ = directory.file(name, false, false)?;
                    if !seen.insert(path) {
                        return Err(AcquisitionError::Inventory);
                    }
                } else if expected
                    .iter()
                    .any(|row| row.path.starts_with(&format!("{path}/")))
                {
                    walk(&directory.child(name)?, &path, expected, seen, depth + 1)?;
                } else {
                    return Err(AcquisitionError::Inventory);
                }
            }
            Ok(())
        }
        let mut seen = BTreeSet::new();
        walk(self, "", expected, &mut seen, 0)?;
        if seen.len() != expected.len() {
            return Err(AcquisitionError::Inventory);
        }
        Ok(())
    }

    pub(crate) fn payload_file(&self, path: &str) -> Result<File, AcquisitionError> {
        if !portable_payload_path(path) {
            return Err(AcquisitionError::UnsafePath);
        }
        let parts: Vec<&str> = path.split('/').collect();
        let mut parent = Self {
            fd: self.fd.try_clone().map_err(|_| AcquisitionError::Io)?,
        };
        for part in &parts[..parts.len() - 1] {
            parent = parent.child(part)?;
        }
        parent.file(parts[parts.len() - 1], false, false)
    }
}

pub fn verify_bundle(
    manifest: &DatasetArtifactManifestV1,
    payload_root: &Path,
    policy: &DatasetPolicy,
) -> Result<VerifiedBundle, AcquisitionError> {
    policy.validate_manifest(manifest)?;
    let directory = Directory::open(payload_root)?;
    directory.check_inventory(&manifest.payload)?;
    let mut files = Vec::with_capacity(4);
    let mut total_bytes = 0_u64;
    for expected in &manifest.payload {
        let mut file = directory.payload_file(&expected.path)?;
        let before = fs::fstat(&file).map_err(|_| AcquisitionError::Io)?;
        if before.st_size < 0 || before.st_size as u64 != expected.bytes {
            return Err(AcquisitionError::Size);
        }
        let verified = verify_payload(expected, &mut file)?;
        let after = fs::fstat(&file).map_err(|_| AcquisitionError::Io)?;
        if before.st_dev != after.st_dev
            || before.st_ino != after.st_ino
            || before.st_size != after.st_size
            || after.st_nlink != 1
        {
            return Err(AcquisitionError::FileKind);
        }
        total_bytes = total_bytes
            .checked_add(verified.bytes)
            .ok_or(AcquisitionError::Size)?;
        files.push(verified);
    }
    // The proof reports bytes observed now. Read-only consumer mounts and a
    // later replay verification are still needed; it is not a future-write seal.
    Ok(VerifiedBundle {
        artifact_id: artifact_id(manifest)?.as_hex().into(),
        evidence_kind: policy.evidence_kind().into(),
        files,
        total_bytes,
    })
}

/// Copy and reverify a complete bundle before same-parent promotion. This
/// implements the algorithm tested here, not the later real mount deployment.
/// `parent` must be a caller-authorized private directory under a single writer.
pub fn publish_bundle(
    manifest: &DatasetArtifactManifestV1,
    source_payload: &Path,
    parent: &Path,
    policy: &DatasetPolicy,
) -> Result<VerifiedBundle, AcquisitionError> {
    let proof = verify_bundle(manifest, source_payload, policy)?;
    let root = Directory::open(parent)?;
    let _lock = root.lock()?;
    let digest = proof.artifact_id();
    if let Ok(existing) = root.child(digest) {
        let mut saved = existing.file("artifact-manifest.json", false, false)?;
        let mut bytes = Vec::new();
        Read::by_ref(&mut saved)
            .take(1_048_577)
            .read_to_end(&mut bytes)
            .map_err(|_| AcquisitionError::Io)?;
        if bytes != canonical_manifest_bytes(manifest)? {
            return Err(AcquisitionError::AlreadyPublished);
        }
        return verify_bundle(manifest, &parent.join(digest).join("payload"), policy);
    }
    match fs::statat(&root.fd, digest, fs::AtFlags::SYMLINK_NOFOLLOW) {
        Ok(_) => return Err(AcquisitionError::AlreadyPublished),
        Err(rustix::io::Errno::NOENT) => (),
        Err(_) => return Err(AcquisitionError::Io),
    }
    // mkdir is exclusive: an interrupted candidate is preserved for explicit
    // recovery rather than reused merely because its pathname exists.
    let temporary_name = format!("pending-{digest}");
    let entry = root.create_child(&temporary_name)?;
    let payload = entry.create_child("payload")?;
    let raw = payload.create_child("raw")?;
    let provenance = payload.create_child("provenance")?;
    let source = Directory::open(source_payload)?;
    for expected in &manifest.payload {
        let (directory_name, filename) = expected
            .path
            .split_once('/')
            .ok_or(AcquisitionError::UnsafePath)?;
        let destination = match directory_name {
            "raw" => &raw,
            "provenance" => &provenance,
            _ => return Err(AcquisitionError::UnsafePath),
        };
        let mut input = source.payload_file(&expected.path)?;
        let mut output = destination.file(filename, true, true)?;
        let copied = std::io::copy(
            &mut Read::by_ref(&mut input).take(expected.bytes + 1),
            &mut output,
        )
        .map_err(|_| AcquisitionError::Io)?;
        if copied != expected.bytes {
            return Err(AcquisitionError::Size);
        }
        output.sync_all().map_err(|_| AcquisitionError::Io)?;
    }
    raw.sync()?;
    provenance.sync()?;
    payload.sync()?;
    let mut manifest_file = entry.file("artifact-manifest.json", true, true)?;
    manifest_file
        .write_all(&canonical_manifest_bytes(manifest)?)
        .map_err(|_| AcquisitionError::Io)?;
    manifest_file.sync_all().map_err(|_| AcquisitionError::Io)?;
    entry.sync()?;
    let copied = verify_bundle(
        manifest,
        &parent.join(&temporary_name).join("payload"),
        policy,
    )?;
    // Caller/lock owns this parent; refuse any existing target, including a
    // symlink or corrupt directory, instead of overwriting it by rename.
    if fs::statat(&root.fd, digest, fs::AtFlags::SYMLINK_NOFOLLOW).is_ok() {
        return Err(AcquisitionError::AlreadyPublished);
    }
    root.rename(&temporary_name, digest)?;
    Ok(copied)
}

pub fn replay_bundle(
    manifest: &DatasetArtifactManifestV1,
    selected_artifact_id: &str,
    entry_root: &Path,
    policy: &DatasetPolicy,
) -> Result<VerifiedBundle, AcquisitionError> {
    let expected = artifact_id(manifest)?;
    if selected_artifact_id != expected.as_hex()
        || entry_root.file_name().and_then(|name| name.to_str()) != Some(selected_artifact_id)
    {
        return Err(AcquisitionError::Policy);
    }
    let directory = Directory::open(entry_root)?;
    let mut file = directory.file("artifact-manifest.json", false, false)?;
    let mut bytes = Vec::new();
    Read::by_ref(&mut file)
        .take(1_048_577)
        .read_to_end(&mut bytes)
        .map_err(|_| AcquisitionError::Io)?;
    if bytes != canonical_manifest_bytes(manifest)? {
        return Err(AcquisitionError::NonCanonical);
    }
    verify_bundle(manifest, &entry_root.join("payload"), policy)
}

// The course's source admission policy. Libraries parse URLs and media types;
// they do not choose eligible corpus objects or grant redistribution rights.

use serde::{Deserialize, Serialize};
use std::fmt;
use url::Url;

use super::canonical_manifest::{
    DatasetArtifactManifestV1, Producer, RedactedEndpoint, lower_sha256, query_inventory_digest,
    validate_manifest_structure,
};
use crate::artifact_identity::{ArtifactDigest, sha256};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum AcquisitionError {
    Schema,
    NonCanonical,
    ManifestBound,
    Inventory,
    UnsafePath,
    Metadata,
    Policy,
    Size,
    Hash,
    Io,
    FileKind,
    ConcurrentWriter,
    Progress,
    Deadline,
    AttemptLimit,
    RedirectLimit,
    TransferBudget,
    Grant,
    Range,
    Validator,
    Encoding,
    Media,
    Url,
    Incomplete,
    AlreadyPublished,
}

impl fmt::Display for AcquisitionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Never interpolate a signed URL, arbitrary path or header into evidence.
        write!(f, "{self:?}")
    }
}
impl std::error::Error for AcquisitionError {}

pub const TINYSTORIES_REVISION: &str = "f54c09fd23315a6f9c86f9dc80f725de7d8f9c64";
pub const PRODUCTION_BODY_CEILING: u64 = 2_000_000_000;
pub const PRODUCTION_WALL_SECONDS: u64 = 14_400;
pub const REDIRECT_HOSTS: [&str; 5] = [
    "huggingface.co",
    "cdn-lfs.huggingface.co",
    "cdn-lfs-us-1.huggingface.co",
    "cdn-lfs-eu-1.huggingface.co",
    "cas-bridge.xethub.hf.co",
];

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SourceSpec {
    pub bytes: u64,
    pub path: String,
    pub requested_url: String,
    pub sha256: String,
    pub source_id: String,
    pub upstream_revision: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct DatasetPolicy {
    attribution_references: Vec<String>,
    attribution_sha256: String,
    body_ceiling: u64,
    domain: String,
    evidence_kind: String,
    language: String,
    license_id: String,
    license_sha256: String,
    producer: Producer,
    selected_source: String,
    sources: [SourceSpec; 2],
    wall_seconds: u64,
}

impl DatasetPolicy {
    /// A named offline policy, not a production flag that relaxes an allowlist.
    /// Production entry points construct `tinystories` and never accept this
    /// policy through caller-supplied JSON.
    pub fn synthetic_fixture() -> Self {
        Self {
            attribution_references: vec!["https://example.invalid/fixtures".into()],
            attribution_sha256: "0d00779105653df98f180d5d8b910ea061782492fcb25e1d955e70453c3456f5"
                .into(),
            body_ceiling: 64,
            domain: "synthetic-policy-fixture".into(),
            evidence_kind: "synthetic-offline-fixture".into(),
            language: "fixture".into(),
            license_id: "LicenseRef-Course-Test-Only".into(),
            license_sha256: "db64e55296d3cb3c38619dae7b7cce54bb74a83956423be38443258ebb0724da"
                .into(),
            producer: Producer {
                config_sha256: "0".repeat(64),
                script_sha256: "0".repeat(64),
            },
            selected_source: "fixture-pair".into(),
            sources: [
                SourceSpec {
                    bytes: 3,
                    path: "raw/train.txt".into(),
                    requested_url: "https://example.invalid/fixtures/train.txt".into(),
                    sha256: "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
                        .into(),
                    source_id: "fixture-train".into(),
