    /// Retained real metadata and actual producer bindings must already exist.
    /// This constructor neither fetches metadata nor decides legal permission.
    pub fn tinystories(
        producer: Producer,
        license_sha256: String,
        attribution_sha256: String,
        attribution_references: Vec<String>,
    ) -> Result<Self, AcquisitionError> {
        for hash in [
            &producer.config_sha256,
            &producer.script_sha256,
            &license_sha256,
            &attribution_sha256,
        ] {
            if !lower_sha256(hash) || hash.bytes().all(|b| b == b'0') {
                return Err(AcquisitionError::Policy);
            }
        }
        if attribution_references.is_empty() || attribution_references.len() > 16 {
            return Err(AcquisitionError::Metadata);
        }
        let make = |name: &str, source_id: &str, bytes: u64, digest: &str| SourceSpec {
            bytes,
            path: format!("raw/{name}"),
            requested_url: format!(
                "https://huggingface.co/datasets/roneneldan/TinyStories/resolve/{TINYSTORIES_REVISION}/{name}"
            ),
            sha256: digest.into(),
            source_id: source_id.into(),
            upstream_revision: TINYSTORIES_REVISION.into(),
        };
        let policy = Self {
            attribution_references,
            attribution_sha256,
            body_ceiling: PRODUCTION_BODY_CEILING,
            domain: "synthetic-short-stories".into(),
            evidence_kind: "production-source-policy".into(),
            language: "en".into(),
            license_id: "CDLA-Sharing-1.0".into(),
            license_sha256,
            producer,
            selected_source: "roneneldan-TinyStories-original-text-pair".into(),
            sources: [
                make(
                    "TinyStories-train.txt",
                    "tinystories-train-raw",
                    1_924_281_556,
                    "c5cf5e22ff13614e830afbe61a99fbcbe8bcb7dd72252b989fa1117a368d401f",
                ),
                make(
                    "TinyStories-valid.txt",
                    "tinystories-valid-raw",
                    19_447_282,
                    "94e431816c4cce81ff71e4408ff8d3bda9a42e8d2663986697c3954288cb38b4",
                ),
            ],
            wall_seconds: PRODUCTION_WALL_SECONDS,
        };
        for reference in &policy.attribution_references {
            let parsed = Url::parse(reference).map_err(|_| AcquisitionError::Metadata)?;
            if parsed.scheme() != "https"
                || parsed.host_str().is_none()
                || !parsed.username().is_empty()
                || parsed.password().is_some()
            {
                return Err(AcquisitionError::Metadata);
            }
        }
        Ok(policy)
    }

    pub fn sources(&self) -> &[SourceSpec; 2] {
        &self.sources
    }
    pub fn body_ceiling(&self) -> u64 {
        self.body_ceiling
    }
    pub fn wall_seconds(&self) -> u64 {
        self.wall_seconds
    }
    pub fn evidence_kind(&self) -> &str {
        &self.evidence_kind
    }
    pub fn is_fixture(&self) -> bool {
        self.evidence_kind == "synthetic-offline-fixture"
    }

    pub fn fixture_with_limits(
        &self,
        body_ceiling: u64,
        wall_seconds: u64,
    ) -> Result<Self, AcquisitionError> {
        if !self.is_fixture() || body_ceiling == 0 || wall_seconds == 0 {
            return Err(AcquisitionError::Policy);
        }
        let mut changed = self.clone();
        changed.body_ceiling = body_ceiling;
        changed.wall_seconds = wall_seconds;
        Ok(changed)
    }

    pub fn fixture_with_payloads(
        &self,
        train: &[u8],
        validation: &[u8],
    ) -> Result<Self, AcquisitionError> {
        if !self.is_fixture() || train.len() > 65_536 || validation.len() > 65_536 {
            return Err(AcquisitionError::Policy);
        }
        let mut changed = self.clone();
        for (source, bytes) in changed.sources.iter_mut().zip([train, validation]) {
            source.bytes = bytes.len() as u64;
            source.sha256 = sha256(bytes).as_hex().into();
        }
        Ok(changed)
    }

    pub fn digest(&self) -> Result<ArtifactDigest, AcquisitionError> {
        let mut bytes = serde_json::to_vec(self).map_err(|_| AcquisitionError::Schema)?;
        bytes.push(b'\n');
        Ok(sha256(&bytes))
    }

    /// Explicit test construction for the attribution counterexample. No
    /// production policy can be modified through this method.
    pub fn fixture_with_attribution(&self, digest: &str) -> Result<Self, AcquisitionError> {
        if !self.is_fixture() || !lower_sha256(digest) {
            return Err(AcquisitionError::Policy);
        }
        let mut changed = self.clone();
        changed.attribution_sha256 = digest.into();
        Ok(changed)
    }

    pub fn validate_manifest(
        &self,
        manifest: &DatasetArtifactManifestV1,
    ) -> Result<(), AcquisitionError> {
        validate_manifest_structure(manifest)?;
        let scope = &manifest.dataset_scope;
        if scope.domain != self.domain
            || scope.language != self.language
            || scope.selected_source != self.selected_source
            || manifest.producer != self.producer
        {
            return Err(AcquisitionError::Policy);
        }
        for (source, expected) in manifest.sources.iter().zip(&self.sources) {
            if source.source_id != expected.source_id
                || source.upstream_revision != expected.upstream_revision
                || source.requested_url != expected.requested_url
                || source.payload_path != expected.path
                || source.bytes != expected.bytes
                || source.sha256 != expected.sha256
            {
                return Err(AcquisitionError::Policy);
            }
            if source.license_id != self.license_id
                || source.license_path != "provenance/LICENSE.txt"
                || source.license_text_sha256 != self.license_sha256
                || source.attribution_path != "provenance/ATTRIBUTION.txt"
                || source.attribution_sha256 != self.attribution_sha256
                || source.attribution_references != self.attribution_references
            {
                return Err(AcquisitionError::Metadata);
            }
            let endpoint = &source.resolved_url;
            if !self.host_allowed(&endpoint.host)
                || !endpoint.path.starts_with('/')
                || endpoint.path.len() > 8192
                || endpoint.path.contains(['?', '#'])
            {
                return Err(AcquisitionError::Url);
            }
        }
        Ok(())
    }

    fn host_allowed(&self, host: &str) -> bool {
        if self.is_fixture() {
            host == "example.invalid"
        } else {
            REDIRECT_HOSTS.contains(&host)
        }
    }

    /// Mature parsing first; the course decides the destination and disclosure
    /// policy. Raw query values remain in this private return value, never in
    /// the redacted endpoint or an error message.
    pub fn admit_endpoint(&self, input: &str) -> Result<(Url, RedactedEndpoint), AcquisitionError> {
        if input.len() > 16_384
            || !input
                .get(..8)
                .is_some_and(|prefix| prefix.eq_ignore_ascii_case("https://"))
            || input.contains('\\')
            || input
                .bytes()
                .any(|byte| byte.is_ascii_control() || byte == b' ')
        {
            return Err(AcquisitionError::Url);
        }
        let parsed = Url::parse(input).map_err(|_| AcquisitionError::Url)?;
        if parsed.scheme() != "https"
            || !parsed.username().is_empty()
            || parsed.password().is_some()
            || parsed.fragment().is_some()
            || parsed.port_or_known_default() != Some(443)
        {
            return Err(AcquisitionError::Url);
        }
        let host = parsed.host_str().ok_or(AcquisitionError::Url)?;
        if !self.host_allowed(host) {
            return Err(AcquisitionError::Url);
        }
        // URL normalization can discard an empty user-info marker. This small
        // negative lexical policy guard rejects that spelling too; URL parsing
        // and percent/host/path semantics are still entirely the library's job.
        if let Some((_, after_scheme)) = input.split_once("://") {
            let authority = after_scheme
                .split(['/', '?', '#'])
                .next()
                .unwrap_or_default();
            if authority.contains('@') {
                return Err(AcquisitionError::Url);
            }
        }
        let mut keys: Vec<String> = parsed
            .query_pairs()
            .map(|(key, _)| key.into_owned())
            .collect();
        keys.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));
        if keys.len() > 128 || keys.iter().any(|key| key.len() > 1024) {
            return Err(AcquisitionError::Url);
        }
        let endpoint = RedactedEndpoint {
            host: host.into(),
            path: parsed.path().into(),
            query_key_inventory_sha256: query_inventory_digest(&keys)?.as_hex().into(),
            query_keys: keys,
            query_values_redacted: true,
            scheme: "https".into(),
            transport_caps_passed: true,
        };
        Ok((parsed, endpoint))
    }

    /// Resolve using the URL library, but apply disclosure/authority guards to
    /// an explicit absolute or network-path spelling before normalization can
    /// discard an empty user-info marker. Relative paths inherit the admitted
    /// base's authority; backslashes and whitespace are not accepted spellings.
    pub fn resolve_redirect(&self, base: &str, location: &str) -> Result<Url, AcquisitionError> {
        if location.len() > 16_384
            || location.contains('\\')
            || location
                .bytes()
                .any(|byte| byte.is_ascii_control() || byte == b' ')
        {
            return Err(AcquisitionError::Url);
        }
        let (base, _) = self.admit_endpoint(base)?;
        let target = if location.starts_with("//") {
            self.admit_endpoint(&format!("https:{location}"))?.0
        } else if Url::parse(location).is_ok() {
            self.admit_endpoint(location)?.0
        } else {
            let joined = base.join(location).map_err(|_| AcquisitionError::Url)?;
            self.admit_endpoint(joined.as_str())?.0
        };
        Ok(target)
    }
}

// Transport plumbing only. The caller supplies a private typed Rust command
// channel and an explicitly authorized request factory (offline in Chapter41).
const MAX_CHUNK = 65_536;
const HEAD_FIELDS = {
  'content-encoding': 'content_encoding',
  'content-length': 'content_length',
  'content-range': 'content_range',
  'content-type': 'content_type',
  etag: 'etag',
};
const refusal = () => new Error('governed transport refused');

function grantOf(reply) {
  const grant = reply?.grant;
  if (!Number.isSafeInteger(grant?.bytes) || grant.bytes < 0 || grant.bytes > MAX_CHUNK
      || !Number.isSafeInteger(grant.sequence) || grant.sequence < 1) throw refusal();
  return grant;
}

function observedHead(response) {
  if (!Number.isInteger(response.statusCode) || !Array.isArray(response.rawHeaders)
      || response.rawHeaders.length % 2 !== 0) throw refusal();
  const head = Object.fromEntries(Object.values(HEAD_FIELDS).map((field) => [field, []]));
  const locations = [];
  for (let index = 0; index < response.rawHeaders.length; index += 2) {
    const name = response.rawHeaders[index];
    const value = response.rawHeaders[index + 1];
    if (typeof name !== 'string' || typeof value !== 'string') throw refusal();
    const field = HEAD_FIELDS[name.toLowerCase()];
    if (field) head[field].push(value);
    if (name.toLowerCase() === 'location') locations.push(value);
  }
  head.status = response.statusCode;
  return { head, locations };
}

function openResponse(requestFactory, permit) {
  if (permit?.kind !== 'request' || permit.method !== 'GET' || typeof permit.url !== 'string'
      || permit.headers?.['accept-encoding'] !== 'identity') throw refusal();
  let request;
  const response = new Promise((resolve, reject) => {
    request = requestFactory(permit.url, { method: 'GET', headers: permit.headers }, (incoming) => {
      incoming.pause();
      // Do not allow a response error to become an unhandled event while Rust
      // persists the head or acknowledges bytes. nextChunk checks this state.
      incoming.on('error', () => {});
      resolve(incoming);
    });
    request.on('error', () => reject(refusal()));
    request.end();
  });
  return { request, response };
}

function nextChunk(response, bytes) {
  return new Promise((resolve, reject) => {
    const cleanup = () => {
      response.off('readable', inspect);
      response.off('end', inspect);
      response.off('error', failed);
      response.off('aborted', failed);
      response.off('close', closed);
    };
    const failed = () => { cleanup(); reject(refusal()); };
    const closed = () => { if (!response.readableEnded) failed(); else inspect(); };
    const inspect = () => {
      if (response.errored || response.readableAborted) return failed();
      if (bytes === 0 && response.readableLength !== 0) return failed();
      const chunk = response.read(bytes);
      if (chunk !== null) {
        cleanup();
        if (!Buffer.isBuffer(chunk) || chunk.length > bytes || chunk.length > MAX_CHUNK) reject(refusal());
        else resolve(chunk);
      } else if (response.readableEnded) { cleanup(); resolve(null); }
    };
    response.on('readable', inspect);
    response.on('end', inspect);
    response.on('error', failed);
    response.on('aborted', failed);
    response.on('close', closed);
    inspect();
  });
}

// Destruction completes before Rust is told that no body bytes were delivered.
async function stopBody(response, request) {
  if (response && !response.closed) {
    const closed = new Promise((resolve) => response.once('close', resolve));
    response.destroy();
    await closed;
  }
  request?.destroy();
}

/** Fetch exactly one Rust-selected source. No URL, policy, retry or filesystem
 * selector is accepted. command(op) returns the worker's private JSON reply.
 * requestFactory has Node https.request's interface; Chapter41 injects it.
 * Returned data is only Rust's file-verification acknowledgment, not a URL.
 */
export async function transport({ command, requestFactory }) {
  if (typeof command !== 'function' || typeof requestFactory !== 'function') throw refusal();
  let timedOut = false;
  const send = async (operation) => {
    if (timedOut) throw refusal();
    const reply = await command(operation);
    if (!reply || reply.kind === 'refused') throw refusal();
    return reply;
  };
  let permit;
  let activeResponse;
  let activeRequest;
  let deadlineTimer;
  try {
    permit = await send({ op: 'start' });
    if (!Number.isSafeInteger(permit.deadline_unix_seconds)) throw refusal();
    const deadline = permit.deadline_unix_seconds;
    const milliseconds = deadline * 1000 - Date.now();
    if (milliseconds <= 0) throw refusal();
    const monotonicEnd = performance.now() + milliseconds;
    const expired = new Promise((resolve, reject) => {
      const arm = () => {
        const remaining = monotonicEnd - performance.now();
        if (remaining <= 0) { timedOut = true; activeResponse?.destroy(); activeRequest?.destroy(); reject(refusal()); }
        else deadlineTimer = setTimeout(arm, Math.min(remaining, 2_147_483_647));
      };
      arm();
    });
    const transfer = async () => { while (true) {
      if (permit.deadline_unix_seconds !== deadline) throw refusal();
      let grant = grantOf(permit);
      const pending = openResponse(requestFactory, permit);
      activeRequest = pending.request;
      activeResponse = await pending.response;
      const { head, locations } = observedHead(activeResponse);
      if ([301, 302, 303, 307, 308].includes(head.status)) {
        await stopBody(activeResponse, activeRequest);
        activeResponse = undefined;
        await send({ op: 'cancel', sequence: grant.sequence });
        if (locations.length !== 1) throw refusal();
        permit = await send({ op: 'redirect', location: locations[0] });
        continue;
      }
      // Rust owns status, encoding, validator, range and length admission.
      await send({ op: 'head', head });
      while (true) {
        const chunk = await nextChunk(activeResponse, grant.bytes);
        if (chunk === null) {
          await send({ op: 'eof', sequence: grant.sequence });
          const verified = await send({ op: 'finish' });
          await stopBody(activeResponse, activeRequest);
          return verified;
        }
        await send({ op: 'body', sequence: grant.sequence, bytes: [...chunk], retain: true });
        grant = grantOf(await send({ op: 'next-grant' }));
      }
    } };
    return await Promise.race([transfer(), expired]);
  } catch {
    await stopBody(activeResponse, activeRequest);
    // Do not manufacture a settlement on transport/worker failure. Rust's
    // durable outstanding grant remains charged conservatively on restoration.
    throw refusal();
  } finally {
    clearTimeout(deadlineTimer);
  }
}

import { spawn } from 'node:child_process';

const refused = () => new Error('governed worker channel refused');
const MAX_LINE = 524_288;

// Fixed binary/JSONL plumbing; no policy override, URL selector or filesystem
// mutation. The owning executor is responsible for the compiled binary/input
// identities and any separate acquisition authority.
export function createWorkerClient({ binary, env }) {
  if (typeof binary !== 'string' || !binary.startsWith('/')
      || !['synthetic-offline-fixture', 'production-source-policy'].includes(env?.CH41_POLICY_KIND)
      || typeof env.CH41_MANIFEST_PATH !== 'string'
      || typeof env.CH41_PROGRESS_DIRECTORY !== 'string') throw refused();
  const child = spawn(binary, [], { env: {
    ...process.env,
    CH41_POLICY_KIND: env.CH41_POLICY_KIND,
    CH41_MANIFEST_PATH: env.CH41_MANIFEST_PATH,
    CH41_PROGRESS_DIRECTORY: env.CH41_PROGRESS_DIRECTORY,
  }, stdio: ['pipe', 'pipe', 'pipe'] });
  let pending;
  let buffered = Buffer.alloc(0);
  let failed = false;
  const fail = () => {
    failed = true;
    pending?.reject(refused());
    pending = undefined;
    child.stdin.destroy();
    child.kill();
  };
  // Never echo private worker diagnostics or signed endpoint strings.
  child.stderr.on('data', () => {});
  child.on('error', fail);
  child.stdin.on('error', fail);
  child.stdout.on('data', (chunk) => {
    buffered = Buffer.concat([buffered, chunk]);
    if (buffered.length > MAX_LINE) return fail();
    const newline = buffered.indexOf(10);
    if (newline < 0) return;
    if (newline !== buffered.length - 1 || !pending) return fail();
    let reply;
    try { reply = JSON.parse(buffered.subarray(0, newline).toString('utf8')); }
    catch { return fail(); }
    buffered = Buffer.alloc(0);
    const resolve = pending.resolve;
    pending = undefined;
    resolve(reply);
  });
  const completion = new Promise((resolve) => child.on('close', (code) => {
    if (pending || buffered.length) fail();
    resolve(code);
  }));
  return {
    command(operation) {
      if (failed || pending || child.exitCode !== null) return Promise.reject(refused());
      const line = JSON.stringify(operation) + '\n';
      if (Buffer.byteLength(line) > MAX_LINE) return Promise.reject(refused());
      return new Promise((resolve, reject) => {
        pending = { resolve, reject };
        child.stdin.write(line, (error) => { if (error) fail(); });
      });
    },
    async close() {
      child.stdin.end();
      if (await completion !== 0 || failed) throw refused();
    },
    destroy: fail,
  };
}

import assert from 'node:assert/strict';
import { EventEmitter } from 'node:events';
import { Readable } from 'node:stream';
import { createWorkerClient } from '../../lib/governed-acquisition-worker-client.mjs';
import { transport } from '../../lib/governed-acquisition-transport.mjs';

const client = createWorkerClient({ binary: process.env.CH41_WORKER_BINARY, env: process.env });
const payloads = [Buffer.from('abc'), Buffer.from('hello\n')];
const requestFactory = (url, options, callback) => {
  assert.equal(options.method, 'GET');
  assert.equal(options.headers['accept-encoding'], 'identity');
  const payload = payloads.shift();
  assert.ok(payload, 'exactly two offline fixture sources');
  const response = Readable.from([payload], { objectMode: false });
  response.statusCode = 200;
  response.rawHeaders = ['Content-Type', 'text/plain', 'Content-Length', String(payload.length), 'ETag', '"fixture-v1"'];
  const request = new EventEmitter();
  request.end = () => queueMicrotask(() => callback(response));
  request.destroy = () => {};
  return request;
};
try {
  for (let source = 0; source < 2; source += 1) {
    const reply = await transport({ command: client.command, requestFactory });
    assert.equal(reply.kind, 'file-verified');
  }
  const { progress } = await client.command({ op: 'status' });
  assert.equal(progress.source_index, 2);
  assert.equal(progress.outstanding_grant, null);
  assert.equal(progress.uncertain_body_bytes, 0);
  assert.equal(progress.sources.reduce((sum, source) => sum + source.acknowledged_body_bytes, 0), 9);
  assert.deepEqual(progress.sources.map((source) => source.attempts), [1, 1]);
  assert.ok(progress.sources.every((source) => source.verified && source.body_eof));
  assert.equal(payloads.length, 0);
  await client.close();
} catch {
  client.destroy();
  throw new Error('offline governed transport round trip refused');
}

